import {URL} from 'node:url';import process from 'node:process';import {execFileSync} from 'node:child_process';
const [moduleFile,dir,mode,release]=process.argv.slice(2);const {TrustRecordStore}=await import(moduleFile);const store=new TrustRecordStore({dir,now:()=> '2026-10-11T00:00:00Z'});
if(mode==='hold'){const read=store.readRecord.bind(store);let first=true;store.readRecord=(...args)=>{const record=read(...args);if(first){first=false;process.send({kind:'held',pid:process.pid});execFileSync(process.execPath,[new URL('./a422-wait-release.mjs',import.meta.url).pathname,release],{timeout:4000});}return record;};try{store.observe({counterparty_identity:'peer',kind:'signature_failure'});process.send({kind:'finished',record:store.get('peer')});}catch(e){process.send({kind:'error',code:e.code,message:e.message});}process.disconnect();}
else {process.on('message',msg=>{try{const result=store.observe({counterparty_identity:'peer',kind:'signature_failure'});process.send({kind:'result',attempt:msg.attempt,count:result.record.signature_failure_count,rejected:result.record.rejected});}catch(e){process.send({kind:'busy',attempt:msg.attempt,code:e.code});}});process.send({kind:'ready',pid:process.pid});}
